#!/usr/bin/env bash
# Behavior tests for core/machines/tables/status-verb.tsv: the status-verb machine, report-only.
# The corpus is generated by seed_lines from a seed; no fleet record is copied. The table is the contract:
# each state's kind says what jg-classify must answer for a line with that verb, and `facts` is replayed
# line for line. The drift guard reports what the table lacks and never fails.
# Run `tests/jg-machine-status.test.sh --drift [status-file...]` to print the drift for this checkout.
set -u
# shellcheck source=tests/lib.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

JM="$ROOT/bin/jg-machine.sh"
TABLE="$ROOT/core/machines/tables/status-verb.tsv"
tab() { local IFS=$'\t'; printf '%s\n' "$*"; }
jm() { OUT=$(bash "$JM" "$@" 2>&1); RC=$?; }

# seed_lines <seed> <out>: three shapes of a status line (plain, stamped, keyed) for every verb the table names.
seed_lines() {
  local RANDOM=$1 v n=0
  while IFS=$'\t' read -r _ v _; do
    n=$((n + 1)); printf '%s: waiting on w%04d\n%s [at=%d]: waiting on w%04d\n%s [key=k%d] [at=%d]: waiting on w%04d\n' \
      "$v" "$RANDOM" "$v" $((1700000000 + RANDOM)) "$RANDOM" "$v" "$n" $((1700000000 + RANDOM)) "$RANDOM"
  done < <(grep -P '^state\t' "$TABLE") > "$2"
}

# drift_arms <file>...: report a case-arm word beside table verbs that the table lacks. Arms only, so prose cannot match.
drift_arms() {
  awk -F'\t' '$1=="state"{print $2}' "$TABLE" | awk -v files="$*" '
    { have[$0] = 1 }
    END { n = split(files, f, " ")
      for (i = 1; i <= n; i++) while ((getline l < f[i]) > 0) {
        arm = ""; nr[f[i]]++
        if (match(l, /^[[:space:]]*[a-z*"|-]+\)/)) arm = substr(l, RSTART, RLENGTH - 1)
        else if (l ~ /^[[:space:]]*case "[a-z"-][^:]*:[[:space:]]*$/) { arm = l; sub(/^[[:space:]]*case /, "", arm); sub(/:[[:space:]]*$/, "", arm) }
        if (arm == "") continue
        gsub(/[", \t]+/, "|", arm); gsub(/\*/, "", arm); m = split(arm, w, "|"); known = 0
        for (j = 1; j <= m; j++) known += (w[j] in have)
        if (known < 2) continue
        for (j = 1; j <= m; j++) if (w[j] ~ /^[a-z][a-z-]*$/ && !(w[j] in have))
          printf "drift: %s:%d: case arm names \"%s\", which status-verb.tsv lacks\n", f[i], nr[f[i]], w[j]
      } }'
}

# drift_reasons <status-file>...: report a line whose verb the table says needs a reason and that carries none.
drift_reasons() {
  local f
  for f in "$@"; do
    awk -F'\t' 'NR==FNR { if ($1=="state" && $5 ~ /reason/) need[$2] = 1; next }
      { v = $0; sub(/[:[].*/, "", v); gsub(/^[ \t]+|[ \t]+$/, "", v); r = $0; sub(/^[^:]*:/, "", r)
        if ((v in need) && r ~ /^[ \t]*$/) printf "drift: %s:%d: %s line without a reason: %s\n", FILENAME, FNR, v, $0 }' "$TABLE" "$f"
  done
}

if [ "${1:-}" = --drift ]; then
  shift
  mapfile -t files < <(grep -rlE --include='*.sh' --include='*.go' needs-decision "$ROOT/bin" "$ROOT/core" | grep -v '/tests/')
  drift_arms "${files[@]}"
  drift_reasons "$@"
  exit 0
fi

T=$(jg_test_tmproot jg-machine-status); mkdir -p "$T/state"
seed_lines 7 "$T/corpus.status"; seed_lines 7 "$T/again.status"
cmp -s "$T/corpus.status" "$T/again.status" || fail "the corpus is not reproducible from its seed"
assert_equals 42 "$(wc -l < "$T/corpus.status" | tr -d ' ')" "three shapes for each of the 14 verbs"

# 1. The table lints, and the corpus verbs replay against it.
jm check status-verb; expect_code 0 "$RC" "the table lints"; assert_equals "ok status-verb: 14 states, 13 edges" "$OUT" "lint golden"
sed -E 's/^([a-z-]+).*/\1/' "$T/corpus.status" > "$T/verbs.corpus"
jm check status-verb --corpus "$T/verbs.corpus"; expect_code 0 "$RC" "every corpus verb is a state"
assert_equals "ok status-verb: 42 lines, 0 findings" "$OUT" "replay golden"
pass "the table lints and the corpus verbs replay"

# 2. The classifier agrees with the table line for line: terminal, relevant, prefix-unrecognized, event.
bash "$ROOT/bin/jg-classify.sh" facts < "$T/corpus.status" | cut -f1,2,6,7 > "$T/facts"
while IFS= read -r l; do
  v=${l%%[ :]*}
  case "$(awk -F'\t' -v v="$v" '$1=="state" && $2==v {print $3}' "$TABLE")" in
    terminal) tab 1 1 0 1 ;; extension) tab 0 1 1 1 ;; initial | normal) tab 0 0 0 1 ;; *) tab "no-row-for-$v" ;;
  esac
done < "$T/corpus.status" > "$T/want"
assert_equals "$(cat "$T/want")" "$(cat "$T/facts")" "jg-classify facts agrees with the table on every line"
pass "jg-classify facts replays the corpus and agrees line for line"

# 3. The extension verbs are rows, so they still surface as themselves; nothing else is an extension.
assert_equals "baseline-attribution checks-lint-pass ready ready-to-sign" \
  "$(awk -F'\t' '$1=="state" && $3=="extension" {print $2}' "$TABLE" | LC_ALL=C sort | tr '\n' ' ' | sed 's/ $//')" "the four lane verbs are extension rows"
pass "ready, ready-to-sign, checks-lint-pass and baseline-attribution are extension rows; progress is a normal row that wakes nobody"

# 4. A verb outside the table is found by name and line, and clears when removed.
{ cat "$T/verbs.corpus"; echo parked; } > "$T/new.corpus"
jm check status-verb --corpus "$T/new.corpus"; expect_code 1 "$RC" "an unregistered verb"
assert_contains "$OUT" "bad status-verb corpus:43: parked is not a state" "check names machine and line"
jm check status-verb --corpus "$T/verbs.corpus"; expect_code 0 "$RC" "green again once removed"
pass "an unregistered verb turns check red and clears when removed"

# 5. AX: one command names the state of a task and its legal moves.
printf 'working [at=1]: start\nblocked [at=2]: waiting on w0001\n' > "$T/state/t1.status"
export JG_STATE_OVERRIDE="$T/state"
jm show status-verb t1; expect_code 0 "$RC" "show"; assert_contains "$OUT" "state	blocked" "the observer reads the last status line"
printf 'working [at=3]: back\n' >> "$T/state/t1.status"
jm next status-verb t1; assert_contains "$OUT" "moves	13" "a working lane may post any other verb"
jm show status-verb none; expect_code 1 "$RC" "a task with no status line is in no state"
pass "show and next answer from the status log"

# 6. Drift guard: a blocked line needs a reason (a quiet checkpoint is never blocked); the classifier verdict does not change.
printf 'blocked [at=5]:\nblocked [at=6]: waiting on w0002\nneeds-decision: \nworking [at=7]:\npaused [at=8]: until w0003\n' > "$T/lines.status"
OUT=$(bash "$0" --drift "$T/lines.status"); RC=$?; expect_code 0 "$RC" "the guard reports and never fails"
assert_contains "$OUT" "lines.status:1: blocked line without a reason" "blocked without a reason is flagged"
assert_contains "$OUT" "lines.status:3: needs-decision line without a reason" "needs-decision without a reason is flagged"
assert_not_contains "$OUT" "lines.status:2:" "a blocked line with a reason is not flagged"
assert_not_contains "$OUT" "lines.status:4:" "working needs no reason"
assert_equals "$(printf '1\t1\n1\t1')" "$(bash "$ROOT/bin/jg-classify.sh" facts < <(sed -n '1,2p' "$T/lines.status") | cut -f1,2)" "the classifier treats both blocked lines alike"
pass "the drift guard flags a blocked line without a reason and the classifier verdict is unchanged"

# 7. Drift guard on case arms: missing verbs are reported with file and line; prose and one-verb arms are not.
mkdir -p "$T/src"
# shellcheck disable=SC2016
printf '%s\n' 'case "$v" in' '  working|paused|parked) a ;;' '  done|failed) b ;;' '  done|close) c ;;' '# working|blocked|stalled) prose' 'x working, paused, lost) is prose' > "$T/src/a.sh"
printf '%s\n' 'switch v {' '	case "done", "failed", "stuck":' '	case "other":' > "$T/src/b.go"
OUT=$(drift_arms "$T/src/a.sh" "$T/src/b.go"); RC=$?; expect_code 0 "$RC" "the arm guard never fails"
assert_equals "$(printf 'drift: %s/src/a.sh:2: case arm names "parked", which status-verb.tsv lacks\ndrift: %s/src/b.go:2: case arm names "stuck", which status-verb.tsv lacks' "$T" "$T")" "$OUT" "only the two arms with a missing verb are reported"
OUT=$(bash "$0" --drift); RC=$?; expect_code 0 "$RC" "the guard reports this checkout and exits 0"
pass "the arm guard reports missing verbs without failing"
